export const readings = [
  {id:'attention',title:'把注意力，留给真正重要的事',subtitle:'从忙碌走向专注',category:'专注与时间',minutes:12,color:'sage',label:'FOCUS',issue:'01',intro:'今天不追求做更多。试着找到一件值得完整投入的事。',paragraphs:[
    ['忙碌，不等于向前','一天结束时，我们很容易用“处理了多少消息”判断自己的努力。但回应别人的问题和推进自己的目标，是两种不同的活动。前者通常有明确提醒，后者却需要自己创造开始的时刻。假如一整天都被提醒推动，最重要的事反而可能没有得到任何完整的时间。'],
    ['找到一个能被看见的结果','“今天学习英语”是一个方向，却还不是容易执行的行动。把它改成“听完一段演讲，用三句话复述，并留下一个纠错记录”，你就知道从哪里开始，也知道什么时候可以结束。一个清楚的小结果，比一个很大的愿望更能减少犹豫。'],
    ['给重要的事一个边界','专注并不要求你拒绝所有事情。先为重要任务留出二十分钟，提前关闭会打断你的提醒，准备好必要的材料。中途想到其他任务时，记在纸上，而不是立即切换。这个边界既保护任务，也保护你免于反复决定“现在该做什么”。'],
    ['为下一次降低难度','结束之前，写下一句：“下次从这里继续。”例如，标注没有理解的段落，或留好下一题。学习的连续性往往来自一个很小的准备动作。今天的成果不只是学会了什么，也包括明天更容易再次开始。']],questions:['你今天最忙的一段时间，实际推进了哪个目标？','把一个模糊计划改写成二十分钟内能交付的结果。'],action:'明天选定一个二十分钟时间段，完成一项有明确结果的小任务。',reference:{title:'延伸阅读：How to Live on 24 Hours a Day',author:'Arnold Bennett',url:'https://www.gutenberg.org/ebooks/2274'}},
  {id:'notes',title:'读完之后，留下自己的答案',subtitle:'把收藏转化为理解',category:'阅读与思考',minutes:15,color:'sand',label:'READ',issue:'02',intro:'好笔记不必很长，但应该能回答：这和我有什么关系？',paragraphs:[
    ['先带一个问题进去','在阅读之前，写下你现在真实遇到的问题。比如“为什么我常常开始，却很少完成？”这个问题不需要覆盖整本书，它的作用是给注意力一个方向。阅读过程中，发现内容无法回答它，也是一种有效判断。'],
    ['区分作者的观点与自己的判断','笔记里至少保留两种声音：作者在主张什么，以及你为什么同意或不同意。把二者混在一起，复习时就很难发现自己的思考发生了什么变化。你可以用“作者认为”和“我的理解”作为两个小标题。'],
    ['用一个例子检验理解','如果一个观点只能用原文解释，你可能还没有真正掌握它。试着找一个工作、学习或生活中的具体场景，再用自己的话讲给没有读过原文的人。这个过程暴露出的空白，比抄下一整页更值得记录。'],
    ['让笔记可以回来找你','在结尾写下一个适用条件：什么时候应该重新看这条笔记？例如“下次准备项目汇报前”。给它一个具体标题和少量标签，知识就有机会在需要时被找回来，而不是只在收藏列表里增长。']],questions:['最近收藏的一条观点，你能不用原话解释吗？','在什么具体场景，你会重新打开这条笔记？'],action:'整理一条旧笔记，补上“我的例子”和“再次使用的场景”。'},
  {id:'small',title:'让开始，比坚持更容易',subtitle:'设计一个能重复的小行动',category:'习惯与成长',minutes:10,color:'lavender',label:'GROW',issue:'03',intro:'先让行动发生，再逐渐提高它的质量。',paragraphs:[
    ['观察开始之前发生了什么','一个计划迟迟没有执行，有时不是因为缺少意志，而是准备步骤太多。打开资料、选择内容、决定时长，每一步都在增加阻力。回想上次没有开始的时刻，找到你真正停住的那一步。'],
    ['把动作缩小到可以立刻完成','把“每天练习表达”缩小成“说清今天的一件事，持续六十秒”。这不是最终目标，而是一个入口。等入口变得熟悉，再增加难度。最低行动应该足够小，让不那么有状态的日子也能完成。'],
    ['用环境承担一部分提醒','在常用设备上保留学习入口，提前选好明天的内容，把笔记放在伸手可及的地方。提醒最好连接到已经存在的动作，例如“晚饭收拾好后，打开今天的精读”。'],
    ['允许调整，不急于归零','某天没有完成，最有价值的问题不是“我为什么又失败”，而是“哪一个条件发生了变化”。修改时间、任务量或开始方式，然后继续。复盘是调整系统，不是给自己下结论。']],questions:['你的计划最常卡在哪个准备步骤？','为忙碌的一天设计一个两分钟版本。'],action:'写下你的最低行动，并把明天所需的材料提前准备好。'},
  {id:'clarity',title:'清晰表达，从一句结论开始',subtitle:'让听众更容易跟上你',category:'沟通与表达',minutes:12,color:'blue',label:'SPEAK',issue:'04',intro:'表达的目标不只是把话说完，而是让对方理解并能回应。',paragraphs:[
    ['给对方一个方向','在展开细节之前，先说明你希望对方知道什么。比如“我建议先做一个小范围测试”。有了这个方向，后面的背景和证据就有了位置。没有方向的细节，再准确也容易让人疲惫。'],
    ['一个观点，配一个具体例子','抽象词可以压缩信息，也可能隐藏分歧。“效率更高”究竟是少一次沟通，还是节省半小时？给出可观察的例子，让对方知道你在说同一件事。'],
    ['为不确定性留下空间','如果依据有限，就说清楚哪些已经确认，哪些仍然是假设。承认不确定，不会自动削弱表达；它让讨论更准确，也让下一步验证有据可循。'],
    ['用请求结束','一段工作表达可以以一个明确请求收尾：“你能在周三前确认这个范围吗？”学习分享则可以用一个问题邀请回应。好的结尾给对方行动的空间，而不是只留下一个句号。']],questions:['你最近一次解释，是先说结论还是先讲背景？','用“结论—例子—请求”重新组织一次真实对话。'],action:'录练六十秒：一个结论、一个例子、一个清晰请求。'},
  {id:'feedback',title:'把反馈，变成下一次的线索',subtitle:'从评价转向改进',category:'学习方法',minutes:12,color:'sage',label:'LEARN',issue:'05',intro:'真正有用的反馈，应该告诉你下一遍具体改什么。',paragraphs:[
    ['不要只问好不好','“我讲得怎么样”通常只能得到宽泛的答案。试着改问：“你在哪一句开始听不懂？”或者“哪个例子最能帮助你理解？”具体问题更容易换来可以使用的信息。'],
    ['一次选一个变化','收到许多建议时，先选择最影响理解的一项。比如先解决顺序，再关注措辞。如果每一遍都同时改所有问题，你很难知道究竟是什么带来了改善。'],
    ['保留第一次的样子','记录原来的句子、修改后的句子以及修改理由。两者之间的差别，就是下一次练习的线索。只保留漂亮的最终版本，会失去理解自己如何改进的机会。'],
    ['把反馈带入新场景','在同一个题目上说得流畅，并不意味着能迁移。换一个小话题，再尝试相同结构。如果还需要提示，把结构卡留在手边。学习不是马上摆脱所有辅助，而是逐步减少依赖。']],questions:['你可以向教练提出哪个更具体的问题？','下次换一个话题时，哪条反馈仍然适用？'],action:'保存一组“原表达—改进表达—原因”，再用新话题重练。'},
  {id:'review',title:'一周之后，如何看见自己的成长',subtitle:'用证据代替模糊的感觉',category:'复盘与行动',minutes:15,color:'sand',label:'REFLECT',issue:'06',intro:'复盘不是证明自己足够努力，而是决定接下来如何投入。',paragraphs:[
    ['先回到具体事实','打开本周留下的笔记、词卡和完成记录。先写发生了什么，再写你如何评价它。把事实和感受分开，可以避免一个糟糕的下午覆盖整周的进展。'],
    ['寻找一次真正的变化','与其列出十项完成的任务，不如找到一个具体变化：一个概念讲得更清楚，一段英文不再需要逐字翻译，或者一个计划开始有了明确边界。变化需要例子来支撑。'],
    ['找出最值得保留的条件','哪次学习最顺畅？它发生在什么时间，使用了什么内容，有没有受到打断？把有用的条件留下来，比单纯要求自己“下周更努力”更有方向。'],
    ['只做一个重要调整','下一周选择一个小调整，并说明如何判断它有没有帮助。例如把英语学习安排在早餐后，观察是否更容易开始。让复盘成为一个持续的小实验，而不是一份越写越长的自我要求。']],questions:['本周有什么变化可以用一条笔记或一次表达证明？','下周只调整一个条件，你会选什么？'],action:'写下一个要保留的做法和一个要改变的条件。'},
];

