export function localDay(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
export function dayIndex(date=new Date()){return Math.floor(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())/86400000);}
export function dueDate(days,date=new Date()){const next=new Date(date);next.setDate(next.getDate()+days);return localDay(next);}
export function dailyReading(date=new Date()){return readings[dayIndex(date)%readings.length];}
export function dailyTalk(date=new Date()){return talks[dayIndex(date)%talks.length];}
